export function socialPanel(handle = "batu") {
  return `<section class="sb-page" data-testid="sb-friend-card"><div class="sb-card"><div class="avatar" aria-hidden="true">${handle.slice(0, 1).toUpperCase()}</div><h2 class="sb-card-name">${handle}</h2><p class="title">✦ Star</p><p class="sub">Active today · 168.2 Kosmo/h</p><div class="verbs"><button>↔<small>Trade</small></button><button>♔<small>Give</small></button><button>✧<small>Challenge</small></button></div></div><p class="sub">Nothing going on with ${handle}.</p><ul class="sb-list sb-links"><li><a href="/friends/${handle}/collection">▤ &nbsp; Collection <span>›</span></a></li><li><a href="/u/${handle}">♙ &nbsp; Profile <span>›</span></a></li></ul><h3>Between you</h3><div class="past"><strong>Trade with ${handle}</strong><span>Done</span><p>Ships and Boats for Pop Singers</p></div><button class="remove" onclick="document.body.dataset.nativeAction='remove'">Remove friend</button></section>`;
}
export function socialFixture(account = "FixturePlayer", selected = "batu") {
  return `<!doctype html><html><head><meta charset="UTF-8"><title>Kosmora social fixture</title><style>
body{margin:0;padding:32px 24px;background:radial-gradient(ellipse at top,#22193e,#0a071b 70%);color:#eeeaf7;font:14px/1.5 system-ui;min-height:100vh}*{box-sizing:border-box}.rail{max-width:1080px;margin:0 auto 24px}.rail a{color:#c9b4e4}.sb{max-width:1080px;margin:auto;display:grid;grid-template-columns:300px minmax(0,1fr);gap:28px;align-items:start}h1{color:#f9e5b1;font:32px Georgia;margin:0 0 20px}.sb-main nav{display:grid;gap:10px}.sb-main nav a{color:#eee5f9;text-decoration:none;padding:18px;background:#19122d;border:1px solid #3d3155;border-radius:10px}.sb-page{border:1px solid #3b2a5a;border-radius:24px;padding:30px 34px;background:linear-gradient(150deg,#1e1539,#0f0b25)}.sb-card{text-align:center}.avatar{background:radial-gradient(circle,#8c6ca1,#302542 70%);border:2px solid #d6bb78;border-radius:50%;width:88px;height:88px;display:grid;place-items:center;font:36px Georgia;color:#f3dba8;margin:auto}.sb-card-name{font:600 25px Georgia;color:#fff2d0;margin:12px 0}.title{color:#ebc770;font:17px Georgia;margin:0 0 10px}.sub{color:#a89abd}.verbs{display:flex;justify-content:center;gap:26px;margin:24px 0 40px}.verbs button{background:linear-gradient(#ffedab,#e7c36d);border:0;border-radius:50%;width:58px;height:58px;font-size:26px;position:relative;color:#211725}.verbs small{position:absolute;top:62px;left:50%;transform:translateX(-50%);font:12px system-ui;color:#eee3f8}.sb-list{list-style:none;padding:0;margin:24px 0}.sb-links a{display:block;padding:15px 0;border-bottom:1px solid #ffffff0c;color:#eeeaf7;text-decoration:none;font-weight:600}.sb-links span{float:right;color:#88769f}h3{text-transform:uppercase;font-size:10px;letter-spacing:.15em;color:#a899c1;margin:25px 0 16px}.past{border-bottom:1px solid #ffffff0c;padding:12px 0;font-size:13px}.past span{float:right;color:#d6c9e8}.past p{color:#a395b9;font-size:12px;margin:2px 0}.remove{border:0;background:none;color:#f0acbb;font-weight:600;padding:0;margin-top:28px;cursor:pointer}@media(max-width:750px){.sb{grid-template-columns:1fr}.sb-page{padding:24px}.sb-main nav{grid-template-columns:1fr 1fr}}
</style></head><body data-native-action=""><aside class="rail"><a href="/u/${account}">${account} · Your profile</a></aside><main class="screen sb" data-testid="social"><div class="sb-main"><h1>Social</h1><nav><a data-friend="batu" href="/social?f=batu">batu</a><a data-friend="FriendB" href="/social?f=FriendB">FriendB</a></nav></div><div class="sb-side">${socialPanel(selected)}</div></main><script>const panels=${JSON.stringify({ batu: socialPanel("batu"), FriendB: socialPanel("FriendB") })}; document.querySelectorAll('[data-friend]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();history.pushState({},'',link.href);document.querySelector('.sb-side').innerHTML=panels[link.dataset.friend];}));</script></body></html>`;
}
